DROP TABLE IF EXISTS `device_usage_info`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `device_usage_info` (
  `id` int NOT NULL AUTO_INCREMENT COMMENT '主键',
  `exe_function_id` char(36) NOT NULL COMMENT '执行模块id',
  `exe_step_id` char(36) CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci NOT NULL DEFAULT '' COMMENT '执行步骤id',
  `device_id` int unsigned NOT NULL DEFAULT '0' COMMENT '设备id',
  `dev_cat` int unsigned NOT NULL COMMENT '设备类型id',
  `use_time` varchar(100) DEFAULT '0' COMMENT '用时时长，单位精确到秒',
  `create_time` datetime DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  PRIMARY KEY (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=79 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci COMMENT='设备使用时间描述';
/*!40101 SET character_set_client = @saved_cs_client */;

